function check(items) {
  var byId = {};
  items.forEach(function (x) { byId[x.id] = x; });
  var orphanFR = [], untestedFR = [], uncoveredUR = [], brokenLinks = [];
  var urCovered = {}, frTested = {};
  items.forEach(function (x) {
    (x.from || []).forEach(function (t) {
      var target = Object.prototype.hasOwnProperty.call(byId, t) ? byId[t] : null;
      if (!target) { brokenLinks.push(x.id + '->' + t); return; }
      if (x.type === 'FR' && target.type === 'UR') urCovered[t] = true;
      if (x.type === 'TC' && target.type === 'FR') frTested[t] = true;
    });
  });
  items.forEach(function (x) {
    if (x.type === 'FR') {
      var ok = (x.from || []).some(function (t) { return byId[t] && byId[t].type === 'UR'; });
      if (!ok) orphanFR.push(x.id);
      if (!frTested[x.id]) untestedFR.push(x.id);
    }
    if (x.type === 'UR' && !urCovered[x.id]) uncoveredUR.push(x.id);
  });
  return { orphanFR: orphanFR.sort(), untestedFR: untestedFR.sort(), uncoveredUR: uncoveredUR.sort(), brokenLinks: brokenLinks.sort() };
}
